SELECT p.gender, COUNT(DISTINCT CASE WHEN l.valueuom = 'mg/L' AND l.value < 200 THEN l.subject_id END) AS normal_count, COUNT(DISTINCT CASE WHEN l.valueuom = 'mg/L' AND l.value BETWEEN 200 AND 400 THEN l.subject_id END) AS borderline_count, COUNT(DISTINCT CASE WHEN l.valueuom = 'mg/L' AND l.value > 400 THEN l.subject_id END) AS elevated_count, CAST(COUNT(DISTINCT CASE WHEN l.valueuom = 'mg/L' AND l.value < 200 THEN l.subject_id END) AS FLOAT) / NULLIF(COUNT(DISTINCT l.subject_id), 0) AS normal_ratio, CAST(COUNT(DISTINCT CASE WHEN l.valueuom = 'mg/L' AND l.value BETWEEN 200 AND 400 THEN l.subject_id END) AS FLOAT) / NULLIF(COUNT(DISTINCT l.subject_id), 0) AS borderline_ratio, CAST(COUNT(DISTINCT CASE WHEN l.valueuom = 'mg/L' AND l.value > 400 THEN l.subject_id END) AS FLOAT) / NULLIF(COUNT(DISTINCT l.subject_id), 0) AS elevated_ratio FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN labevents l ON a.subject_id = l.subject_id AND a.hadm_id = l.hadm_id WHERE p.gender = 'M' AND p.anchor_age = 84 AND p.anchor_year BETWEEN 79 AND 89 AND l.itemid = 87187880 AND l.valueuom = 'mg/L' GROUP BY p.gender;